xt="">Read the full manifesto</span><!-- /wp:atomic-wind/text --><!-- wp:atomic-wind/icon {"icon":"arrow-right","className":"size-4 m-0"} /--></a><!-- /wp:atomic-wind/link --></div><!-- /wp:atomic-wind/box --></div><!-- /wp:atomic-wind/box --></div><!-- /wp:atomic-wind/box --></section><!-- /wp:atomic-wind/box -->',
